  const news = [{"headline":"Ṣẹwà is Spotify’s EQUAL Africa artist for November","artist":"Ṣẹwà","date":"2026-11-07","summary":"Spotify’s November EQUAL Africa spotlight goes to Nigerian singer and producer Ṣẹwà. Her featured song, Lése, combines Afro-soul with jazz and rock textures. TurnTable’s interview explores her independent production and live-band approach.","url":"https://turntablecharts.com/news/2314-spotify-names-afro-soul-singer-and-producer-sewa-as-november-s-equal-africa-artist","source":"TurnTable Charts"},{"headline":"Darlsweetboy releases SHENKA","artist":"Darlsweetboy","date":"2026-11-06","summary":"TurnTable profiles Darlsweetboy’s new single SHENKA, produced by Shallythechampion. The independent artist pairs a celebration of progress with reflections on the work behind it. The report links the release to his wider catalogue.","url":"https://turntablecharts.com/news/2313-darlsweetboy-counts-the-cost-of-the-come-up-on-shenka","source":"TurnTable Charts"},{"headline":"Runtown’s Surround Sound concert film arrives","artist":"Runtown","date":"2026-11-05","summary":"Spotify premiered Runtown’s Surround Sound concert film on 4 November. Filmed in Lagos and directed by Tim Horwood, it follows four chapters of his catalogue. The report’s listening figures are explicitly dated 15 September.","url":"https://turntablecharts.com/news/2311-ten-years-of-mad-over-you-runtown-s-story-comes-to-spotify-in-a-new-surround-sound-film","source":"TurnTable Charts"},{"headline":"FOLA holds No. 1 as Asake returns to the top three","artist":"FOLA / Asake","date":"2026-11-03","summary":"FOLA’s miss u ii (nriri) spends a third week at No. 1 on TurnTable’s official Nigerian singles chart. Seyi Vibez’s Ilome is second and Asake’s Gratitude rises to third. Olamide’s Burukutu enters at No. 9.","url":"https://turntablecharts.com/news/2302-fola-s-miss-u-ii-nriri-holds-at-no-1-for-a-third-consecutive-week-asake-s-gratitude-returns-to-no-3-in-its-26th-week-on-the-chart","source":"TurnTable Charts"},{"headline":"FOLA’s year in numbers","artist":"FOLA","date":"2026-10-23","summary":"TurnTable’s year-in-review reports five Nigerian No. 1 songs for FOLA in 2026. It also reports that his second album, 9, entered the albums chart at No. 1. These are the publisher’s Nigerian chart figures, separate from the global Spotify totals used in our stream tables.","url":"https://www.turntablecharts.com/news/2300-fola-s-2026-the-numbers-behind-a-striker-s-year","source":"TurnTable Charts"},{"headline":"FOLA takes No. 1 on both official charts","artist":"FOLA","date":"2026-10-20","summary":"TurnTable reports that miss u ii (nriri) reached No. 1 on its Nigerian singles chart, while 9 debuted atop the albums chart. Seyi Vibez’s Ilome moved to No. 2 and Rema’s Oh No rose to No. 3 on the singles chart. The original report remains linked for its period and methodology.","url":"https://www.turntablecharts.com/news/2299-fola-s-miss-u-ii-nriri-rockets-to-no-1-seyi-vibez-s-back-2-u-rebounds-to-its-no-4-peak","source":"TurnTable Charts"},{"headline":"Ilome holds the official Nigeria No. 1","artist":"Seyi Vibez","date":"2026-10-13","summary":"TurnTable reports a second week at No. 1 for Ilome. B4 B4 rises to No. 2, while Blaqbonez and Asake’s Ikebe 3000 enters at No. 5. The published chart covers 2–8 October.","url":"https://www.turntablecharts.com/news/2290-seyi-vibez-s-ilome-spends-a-second-week-at-no-1-blaqbonez-asake-s-ikebe-3000-launches-at-no-5","source":"TurnTable Charts"},{"headline":"Fireboy’s ZUKO rollout takes shape","artist":"Fireboy DML","date":"2026-10-13","summary":"TurnTable’s preview discusses CLAAT! with Masicka and IMALI with JAZZWRLD and Thukuthela. It describes an ongoing rollout; the full project is not treated as a released, fully streamed album in our list.","url":"https://www.turntablecharts.com/news/2291-fireboy-dml-s-zuko-everything-we-know-so-far","source":"TurnTable Charts"},{"headline":"FOLA returns with 9","artist":"FOLA","date":"2026-10-09","summary":"TurnTable reviews FOLA’s 14-track second album, with appearances from Davido, Ayra Starr, BNXN, Darkoo, Bella Shmurda and Zlatan. The review follows his run of singles into a new album cycle.","url":"https://www.turntablecharts.com/news/2288-fola-s-9-a-striker-at-the-peak-of-his-game","source":"TurnTable Charts"}];
  const addSection = (id, html) => { if (document.getElementById(id)) return; const s=document.createElement("section"); s.id=id; s.className="tab-content supplement-section"; s.innerHTML=html; main.appendChild(s); };
  addSection("top100", `<p class="eyebrow">Direct chart pass-through</p><h2>Nigeria Top 100 Songs</h2><p class="supplement-intro">Weekly chart snapshot from <a href="https://www.turntablecharts.com/charts/1" target="_blank" rel="noopener noreferrer">TurnTable Charts</a>. This table is not scored by Afri Index; it preserves the chart’s own rank, movement and metadata.</p><p class="source-tag">Chart week 23 Oct 2026 – 29 Oct 2026 · checked 9 Nov 2026 · 100 entries · TurnTable Charts ↗</p><table class="top100-table"><thead><tr><th>Rank</th><th>Title</th><th>Artist</th><th>Last week</th><th>Weeks</th><th>Peak</th><th>Status</th></tr></thead><tbody>${top100.map(r=>{const movement=r[6] || (r[3]<0?"RE":r[3]===r[0]?"—":r[3]>r[0]?`↑ ${r[3]-r[0]}`:`↓ ${r[0]-r[3]}`);const movementClass=movement.startsWith("↑")?"movement-up":movement.startsWith("↓")?"movement-down":"movement-flat";return `<tr><td>${r[0]}</td><td>${esc(r[1])}</td><td>${esc(r[2])}</td><td>${r[3]>0?r[3]:"—"}</td><td>${r[4]}</td><td>${r[5]}</td><td class="${movementClass}">${esc(movement)}</td></tr>`}).join("")}</tbody></table><p class="archive-note">The latest TurnTable chart available when checked on 9 Nov 2026 covers 23 Oct 2026 – 29 Oct 2026.</p>`);
  addSection("news", `<p class="eyebrow">Sourced editorial notes</p><h2>Artist News</h2><p class="supplement-intro">Short, reverse-chronological updates. Every item links to a checkable source or an Afri Index audit page; this is manually curated alongside the data refresh.</p><div class="news-list">${news.map(n=>`<article class="news-item"><h3>${esc(n.headline)}</h3><p>${esc(n.summary)}</p><small>${esc(n.date)} · ${esc(n.artist)} · <a href="${esc(n.url)}">${esc(n.source)} ↗</a></small></article>`).join("")}</div>`);
  const method = document.getElementById("method");
  if (method && !method.querySelector(".master-method-notes")) {
    const notes = document.createElement("div"); notes.className="master-method-notes yearly-method mt-8";
    notes.innerHTML = `<h3 class="font-semibold text-lg mb-2">Source and scoring notes</h3><p class="text-sm text-gray-700"><strong>Awards:</strong> Wikipedia’s English artist page or dedicated awards list is the coverage guide, not the final authority. Published totals and award-body breakdowns are retained; only individually highlighted results with a direct non-Wikipedia source appear as verified highlights. Profiles without a structured published total keep an explicit audited coverage state.</p><p class="text-sm text-gray-700 mt-3"><strong>Streams:</strong> Sourced audio streams carry 17% of Current; monthly-listener weighting is removed. The locked editorial contribution is normalized to 83 points; the audio-stream index supplies up to 17. All candidates use the same available audio platforms for scoring. Per-platform counts, sources, publisher dates and check dates remain separate; unavailable counts stay null. YouTube video views never become audio streams.</p><p class="text-sm text-gray-700 mt-3"><strong>Release year:</strong> the active-year lists contain verified releases from that year, ordered by lifetime Spotify totals. They are not year-to-date consumption charts. Historical editions keep their original coverage notes.</p><p class="text-sm text-gray-700 mt-3"><strong>Certifications:</strong> TurnTable Charts’ Nigerian ledger is the local reference; international plaques link to RIAA, BPI, Music Canada or SNEP. Failed register pages retain prior matches and every unmatched artist receives a dated no-match audit state.</p><p class="text-sm text-gray-700 mt-3"><strong>Top 100:</strong> the weekly Nigeria chart is a dated TurnTable pass-through, not an Afri Index score. <strong>Artists to Watch:</strong> entries remain unranked and contain no invented biography details. <strong>News:</strong> every item now links to a checkable public source.</p>`;
    method.append(notes);
  }
  const input = document.getElementById("artist-global-search"), results=document.getElementById("artist-search-results");
  if(input && results){
    const legacy=["2Baba","P-Square","D'banj","Wande Coal","Yemi Alade","Fela Kuti","Sarkodie","Don Jazzy","Mayorkun","Zinoleesky","Priesst","6uff","T.I Blaze"];
    const list=Array.from(new Map([...((window.AFRI_CURRENT_ARTISTS||[]).map(a=>[a.name,a])),...legacy.map(name=>[name,{name,slug:name.toLowerCase().replace(/[^a-z0-9]+/g,"-")}])]).values());
    const render=(q)=>{const hits=list.filter(a=>a.name.toLowerCase().includes(q.trim().toLowerCase())).slice(0,8); results.innerHTML=hits.map(a=>`<button type="button" role="option" data-search-slug="${esc(a.slug)}">${esc(a.name)}</button>`).join(""); results.classList.toggle("open",!!q&&hits.length>0);};
    input.addEventListener("input",e=>render(e.target.value)); input.addEventListener("keydown",e=>{if(e.key==="Escape"){results.classList.remove("open");input.blur();} if(e.key==="Enter"){const first=results.querySelector("button"); if(first){first.click();e.preventDefault();}}}); results.addEventListener("click",e=>{const b=e.target.closest("[data-search-slug]");if(!b)return; results.classList.remove("open");input.value=""; if(typeof window.openCurrentArtist==="function") window.openCurrentArtist(b.dataset.searchSlug); else if(typeof window.openArtist==="function") window.openArtist(b.dataset.searchSlug);});
  }
