  const legacyNames=["Burna Boy","Davido","Wizkid","Tems","Asake","Rema","Omah Lay","Olamide","Tiwa Savage","2Baba","Ayra Starr","CKay","Seyi Vibez","Fireboy DML","Victony","Kizz Daniel","Tyla","Yemi Alade","Wande Coal"];
  legacyNames.forEach(name=>{const img=Array.from(document.querySelectorAll("img[alt]")).find(node=>(node.alt||"").trim().toLowerCase()===name.toLowerCase()); if(!img || currentByName.has(name.toLowerCase())) return; const page=encodeURIComponent(name.replace(/\s+/g,"_")); fetch(`https://en.wikipedia.org/api/rest_v1/page/summary/${page}`).then(r=>r.ok?r.json():null).then(j=>{const src=j?.thumbnail?.source; if(src) img.src=src;}).catch(()=>{});});
